## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/acneLogic.ts`

```typescript
/**
 * Acne Vulgaris Clinical Logic Engine
 *
 * Based on:
 * - AAD 2024 Guidelines of Care for the Management of Acne Vulgaris
 *   (PMID: 38300170)
 * - AAD 2016 Acne Guidelines (PMID: 26897386)
 * - Antibiotic Stewardship in Acne — limit duration, avoid monotherapy
 * - Isotretinoin REMS (iPLEDGE) requirements
 */

export type AcneSeverity = "mild" | "moderate" | "severe";
export type AcneType = "comedonal" | "papulopustular" | "nodulocystic" | "mixed";
export type PatientSex = "male" | "female" | "other";
export type PriorAcneTreatment = "none" | "topicals_only" | "topicals_and_oral_antibiotics" | "prior_isotretinoin";

export interface AcneInput {
  // Severity and morphology
  pgaScore: 0 | 1 | 2 | 3 | 4 | 5; // 0=clear, 1=almost clear, 2=mild, 3=moderate, 4=severe, 5=very severe
  acneType: AcneType;
  hasScarring: boolean; // psychosocial burden or scarring → consider severe
  hasPsychosocialBurden: boolean;

  // Demographics
  patientSex: PatientSex;
  ageYears: number;

  // Prior treatment
  priorTreatment: PriorAcneTreatment;
  priorAntibioticMonths: number; // months of prior antibiotic use

  // Hormonal considerations (female patients)
  hasPCOS: boolean;
  isPregnant: boolean;
  isBreastfeeding: boolean;
  desireContraception: boolean;

  // Comorbidities
  hasHyperkalemiaRisk: boolean; // for spironolactone monitoring
  hasHyperlipidemia: boolean; // isotretinoin monitoring
  hasLiverDisease: boolean; // isotretinoin/minocycline caution
  hasInflammatoryBowelDisease: boolean; // isotretinoin — no proven link per AAD 2024

  // Clinical flags
  hasDrugInducedAcne: boolean; // steroids, lithium, anticonvulsants
  hasTrunkInvolvement: boolean; // affects treatment choice
  hasNodulesCysts: boolean; // triggers isotretinoin consideration
}

export interface AcneRecommendation {
  severity: AcneSeverity;
  primaryRecommendation: string;
  treatmentPathway: string;
  specificAgents: string[];
  agentsToAvoid: string[];
  hormonalOptions: string[];
  isotretinoinIndicated: boolean;
  isotretinoinNotes: string[];
  antibioticStewardshipNotes: string[];
  monitoringPlan: string[];
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
  sharedDecisionPoints: string[];
}

function classifyAcneSeverity(input: AcneInput): AcneSeverity {
  // PGA-based primary classification
  if (input.pgaScore <= 2) {
    // Override to severe if scarring or psychosocial burden present
    if (input.hasScarring || input.hasPsychosocialBurden) return "severe";
    return "mild";
  }
  if (input.pgaScore === 3) {
    if (input.hasScarring || input.hasPsychosocialBurden) return "severe";
    return "moderate";
  }
  // PGA 4-5 or nodulocystic
  return "severe";
}

export function assessAcne(input: AcneInput): AcneRecommendation {
  const severity = classifyAcneSeverity(input);

  const urgentFlags: string[] = [];
  const specificAgents: string[] = [];
  const agentsToAvoid: string[] = [];
  const hormonalOptions: string[] = [];
  const isotretinoinNotes: string[] = [];
  const antibioticStewardshipNotes: string[] = [];
  const nextSteps: string[] = [];
  const monitoringPlan: string[] = [];
  const sharedDecisionPoints: string[] = [];
  let isotretinoinIndicated = false;

  // Urgent flags
  if (input.isPregnant) {
    urgentFlags.push("PREGNANCY: Isotretinoin is absolutely contraindicated. Avoid tetracyclines (doxycycline, minocycline). Topical azelaic acid and erythromycin are safest options.");
  }
  if (input.hasDrugInducedAcne) {
    urgentFlags.push("Drug-induced acne suspected — review medications (corticosteroids, lithium, anticonvulsants, anabolic steroids) before initiating acne therapy");
  }

  let primaryRecommendation = "";
  let treatmentPathway = "";
  let evidenceLevel = "";

  if (severity === "mild") {
    primaryRecommendation = "Topical multimodal combination therapy — avoid antibiotic monotherapy";
    treatmentPathway =
      "Step 1: Topical retinoid (adapalene 0.1-0.3%, tretinoin 0.025-0.1%, or tazarotene) — cornerstone of acne therapy. " +
      "Step 2: Add benzoyl peroxide (BPO) 2.5-10% — antibiotic resistance prevention. " +
      "Step 3: Fixed-dose combination (retinoid + BPO, or antibiotic + BPO) for convenience and adherence. " +
      "Step 4: Reassess at 8-12 weeks; escalate if inadequate response.";

    specificAgents.push("Adapalene 0.1% gel — first-line retinoid; OTC available; well tolerated");
    specificAgents.push("Benzoyl peroxide 2.5-5% — essential for antibiotic resistance prevention");
    specificAgents.push("Fixed-dose adapalene 0.1% + BPO 2.5% (Epiduo) — convenient combination");
    specificAgents.push("Azelaic acid 15-20% — comedolytic + anti-inflammatory; safe in pregnancy");
    specificAgents.push("Salicylic acid 0.5-2% — comedolytic; OTC option for mild comedonal acne");

    if (input.acneType === "comedonal") {
      specificAgents.push("Topical retinoid monotherapy acceptable for pure comedonal acne");
    }

    evidenceLevel = "Strong recommendation (AAD 2024, Level A)";

  } else if (severity === "moderate") {
    primaryRecommendation = "Combination topical + systemic therapy; antibiotic stewardship is mandatory";
    treatmentPathway =
      "Step 1: Topical retinoid + BPO (continue throughout). " +
      "Step 2: Add oral antibiotic (doxycycline 100mg daily preferred) — limit to ≤3-6 months; always combine with BPO. " +
      "Step 3: Add hormonal therapy in females (spironolactone 50-200mg or COC). " +
      "Step 4: If inadequate response after 3 months of antibiotics: escalate to isotretinoin. " +
      "Step 5: Intralesional corticosteroids for individual large nodules (rapid response).";

    specificAgents.push("Doxycycline 100mg daily — preferred oral antibiotic (AAD 2024 conditional recommendation over azithromycin)");
    specificAgents.push("Fixed-dose topical antibiotic + BPO (clindamycin 1% + BPO 5%) — reduces resistance");
    specificAgents.push("Adapalene 0.3% + BPO 2.5% (Epiduo Forte) — for moderate-severe papulopustular");
    specificAgents.push("Sarecycline 1.5mg/kg/day — narrow-spectrum tetracycline; less GI side effects");
    specificAgents.push("Intralesional triamcinolone 2.5-5mg/mL — for individual nodules/cysts");

    antibioticStewardshipNotes.push("Limit oral antibiotic duration to ≤3-6 months (AAD 2024 strong recommendation)");
    antibioticStewardshipNotes.push("NEVER use topical antibiotic monotherapy — always combine with BPO");
    antibioticStewardshipNotes.push("Do not use oral and topical antibiotics simultaneously");
    antibioticStewardshipNotes.push("Continue BPO throughout antibiotic course to prevent resistance");

    agentsToAvoid.push("Oral antibiotic monotherapy — strongly not recommended (AAD 2024)");
    agentsToAvoid.push("Topical antibiotic monotherapy — promotes resistance");
    agentsToAvoid.push("Azithromycin — less preferred than doxycycline per AAD 2024");

    evidenceLevel = "Strong recommendation (AAD 2024, Level A)";

  } else {
    // Severe
    primaryRecommendation = "Oral isotretinoin is strongly recommended for severe acne or treatment-refractory moderate acne";
    treatmentPathway =
      "Step 1: Oral isotretinoin 0.5-1mg/kg/day — standard daily dosing preferred over intermittent (AAD 2024). " +
      "Step 2: Target cumulative dose 120-150mg/kg for sustained remission. " +
      "Step 3: Continue topical retinoid + BPO during and after isotretinoin course. " +
      "Step 4: Intralesional corticosteroids for acute nodule management during initiation. " +
      "Step 5: Hormonal therapy (females) as adjunct or maintenance after isotretinoin.";

    isotretinoinIndicated = true;
    isotretinoinNotes.push("Isotretinoin strongly recommended for severe acne (PGA 4-5), nodulocystic acne, or acne with scarring/psychosocial burden (AAD 2024)");
    isotretinoinNotes.push("iPLEDGE REMS enrollment required for all patients in the US");
    isotretinoinNotes.push("Pregnancy prevention mandatory for persons of childbearing potential — 2 forms of contraception or abstinence");
    isotretinoinNotes.push("Standard isotretinoin or lidose-isotretinoin (Absorica LD) — both conditionally recommended by AAD 2024");
    isotretinoinNotes.push("Traditional daily dosing conditionally recommended over intermittent/low-dose for severe acne");
    isotretinoinNotes.push("AAD 2024: No proven increased risk of neuropsychiatric conditions or IBD in population-based studies");

    specificAgents.push("Isotretinoin 0.5-1mg/kg/day orally — standard daily dosing");
    specificAgents.push("Intralesional triamcinolone — bridge therapy for acute nodule flare");
    specificAgents.push("Topical retinoid + BPO — continue throughout course");

    monitoringPlan.push("Isotretinoin: LFTs and lipids at baseline and monthly (or as clinically indicated)");
    monitoringPlan.push("CBC monitoring not needed in healthy patients (AAD 2024)");
    monitoringPlan.push("Monthly pregnancy test for persons of childbearing potential (iPLEDGE)");
    monitoringPlan.push("Reassess at 1 month, then every 1-2 months during course");

    evidenceLevel = "Strong recommendation (AAD 2024, Level A)";
  }

  // Hormonal therapy (females)
  if (input.patientSex === "female" && !input.isPregnant && !input.isBreastfeeding) {
    if (input.hasPCOS || input.desireContraception || severity !== "mild") {
      hormonalOptions.push("Spironolactone 50-200mg daily — conditionally recommended; anti-androgen; effective for hormonal acne");
      hormonalOptions.push("Combined oral contraceptive (COC) — FDA-approved for acne; ethinyl estradiol-based");
      hormonalOptions.push("Clascoterone 1% cream — topical anti-androgen; FDA approved for acne ages ≥12");

      if (input.hasHyperkalemiaRisk) {
        monitoringPlan.push("Spironolactone: check potassium at baseline if risk factors for hyperkalemia (AAD 2024 — routine monitoring not needed in healthy patients)");
      }

      sharedDecisionPoints.push("Hormonal therapy effective for females with hormonal acne patterns (jawline, chin, perimenstrual flares)");
      sharedDecisionPoints.push("Spironolactone: potassium monitoring only needed with risk factors per AAD 2024");
    }
  }

  // Pregnancy-specific
  if (input.isPregnant || input.isBreastfeeding) {
    agentsToAvoid.push("Isotretinoin — absolutely contraindicated in pregnancy (Category X)");
    agentsToAvoid.push("Doxycycline, minocycline, tetracycline — contraindicated in pregnancy");
    agentsToAvoid.push("Spironolactone — avoid in pregnancy");
    specificAgents.push("Topical azelaic acid 15-20% — safe in pregnancy");
    specificAgents.push("Topical erythromycin + BPO — safe in pregnancy");
    specificAgents.push("Topical clindamycin + BPO — generally considered safe in pregnancy");
  }

  // Prior antibiotic overuse
  if (input.priorAntibioticMonths > 6) {
    antibioticStewardshipNotes.push(`Prior antibiotic use: ${input.priorAntibioticMonths} months — consider antibiotic holiday; escalate to isotretinoin or hormonal therapy`);
    urgentFlags.push("Extended prior antibiotic use detected — antibiotic resistance risk; prioritize non-antibiotic systemic options");
  }

  // Scarring
  if (input.hasScarring) {
    nextSteps.push("Active scarring: expedite isotretinoin referral — early treatment prevents progressive scarring");
    nextSteps.push("Consider dermatology referral for scar treatment (fractional laser, chemical peels, microneedling) after acne control");
  }

  // Universal next steps
  nextSteps.push("Reassess at 8-12 weeks; document PGA score at each visit");
  nextSteps.push("Counsel on realistic expectations: 6-8 weeks for topical response, 3 months for systemic");
  nextSteps.push("Sunscreen daily — retinoids increase photosensitivity");
  nextSteps.push("Gentle non-comedogenic skincare; avoid abrasive scrubs");

  sharedDecisionPoints.push("Antibiotic stewardship: limit duration, always combine with BPO");
  sharedDecisionPoints.push("Isotretinoin: discuss iPLEDGE requirements, side effect profile, and expected remission rates");
  sharedDecisionPoints.push("Psychosocial impact: screen for depression/anxiety; acne significantly affects quality of life");

  return {
    severity,
    primaryRecommendation,
    treatmentPathway,
    specificAgents,
    agentsToAvoid,
    hormonalOptions,
    isotretinoinIndicated,
    isotretinoinNotes,
    antibioticStewardshipNotes,
    monitoringPlan,
    urgentFlags,
    nextSteps,
    evidenceLevel,
    sharedDecisionPoints,
    references: [
      {
        citation: "AAD 2024 Guidelines of Care for the Management of Acne Vulgaris — Zaenglein AL et al.",
        pmid: "38300170",
        url: "https://pubmed.ncbi.nlm.nih.gov/38300170/",
      },
      {
        citation: "AAD 2016 Guidelines of Care for the Management of Acne Vulgaris — Zaenglein AL et al.",
        pmid: "26897386",
        url: "https://pubmed.ncbi.nlm.nih.gov/26897386/",
      },
      {
        citation: "Topical Retinoids in Acne Vulgaris: A Systematic Review — Leyden J et al.",
        pmid: "30674002",
        url: "https://pubmed.ncbi.nlm.nih.gov/30674002/",
      },
      {
        citation: "Topical Benzoyl Peroxide for Acne — Dréno B et al.",
        pmid: "32175593",
        url: "https://pubmed.ncbi.nlm.nih.gov/32175593/",
      },
      {
        citation: "Oral Doxycycline in the Management of Acne Vulgaris — Garner SE et al.",
        pmid: "4445892",
        url: "https://pubmed.ncbi.nlm.nih.gov/4445892/",
      },
    ],
  };
}

export function getAcneSeverityColor(severity: AcneSeverity): string {
  switch (severity) {
    case "mild": return "text-green-700 bg-green-50 border-green-200";
    case "moderate": return "text-amber-700 bg-amber-50 border-amber-200";
    case "severe": return "text-red-700 bg-red-50 border-red-200";
  }
}

export function getAcneSeverityBadge(severity: AcneSeverity): string {
  switch (severity) {
    case "mild": return "Mild Acne";
    case "moderate": return "Moderate Acne";
    case "severe": return "Severe Acne";
  }
}
